// AiXenix Cosmos Lab web client: the sandbox's frame source for the 3D view (one atomic snapshot per frame).

import { sameIdentity, sessionStore, type SessionState } from '../../app/session';
import { settingsStore } from '../../app/settings';
import { displayNames } from '../../app/names';
import type { ViewFrame } from '../../render/SpaceView';
import type { FrameSource } from '../Viewport';

let lastInputs: unknown[] = [];
let lastFrame: ViewFrame | null = null;

function build(s: SessionState): ViewFrame | null {
  const snap = s.snapshot ?? s.preview;
  if (!snap) return null;
  const lang = settingsStore.get().lang;
  const inputs = [snap, s.appearance, s.tracerLooks, s.selection, s.scene, lang];
  if (lastFrame && inputs.every((v, i) => v === lastInputs[i])) return lastFrame;
  lastInputs = inputs;
  const sky = (s.scene as unknown as { sky_profile?: string } | null)?.sky_profile ?? 'Sky_MilkyWay';
  lastFrame = {
    snapshot: snap,
    appearance: s.appearance,
    tracerLooks: s.tracerLooks,
    selectedId: s.selection && (sameIdentity(s.selection, snap) || snap.worldId === -1) ? s.selection.id : null,
    sky,
    names: displayNames(snap, lang, s.scene, s.appearance),
  };
  return lastFrame;
}

export const sandboxSource: FrameSource = {
  get: () => build(sessionStore.get()),
  subscribe: (l) => {
    const a = sessionStore.subscribe(l);
    const b = settingsStore.subscribe(l);
    return () => {
      a();
      b();
    };
  },
};
