// AiXenix Cosmos Lab web client: the sandbox: 3D world, time bar, tools, bodies/worlds panel, inspector, saves.

import { lazy, Suspense, useCallback, useEffect, useState, type ComponentType } from 'react';
import { navigate, type Route } from '../app/router';
import { setSetting, settingsStore, useLang, useT } from '../app/settings';
import { useStore } from '../app/store';
import { askConfirm } from '../app/notices';
import {
  bodyOf,
  currentWorld,
  ensureEngine,
  focusBody,
  openCatalogueScene,
  pause,
  readAutosave,
  loadSaveRecord,
  removeBody,
  requestFit,
  resetWorld,
  retryEngine,
  selectBody,
  sessionStore,
  startAutosave,
  stepOnce,
  togglePlay,
  nudgeRate,
  undo,
  redo,
} from '../app/session';
import type { SaveRecord } from '../app/saves';
import { bodyDisplayName } from '../app/names';
import { formatQuantity, formatRelativeTime } from '../app/units';
import { tx } from '../content/catalog';
import { CATALOG_INDEX } from '../content/catalog.generated';
import { Viewport, type CameraRequest } from './Viewport';
import { sandboxSource } from './sandbox/source';
import { TimeBar } from './sandbox/TimeBar';
import { LeftPanel, type LeftTab } from './sandbox/LeftPanel';
import { WorldOverview, WorldStatusChip } from './sandbox/WorldOverview';
import { SavesPanel } from './sandbox/SavesPanel';
import { confirmReplace } from '../app/replaceGuard';
import { loadCosmos, type Cosmos } from '../app/cosmos';
import { enterStarSystem, mapRouteFor } from '../app/universe';
import { notify } from '../app/notices';
import { ActionsMenu, HelpMenu, ViewMenu } from './sandbox/Popovers';
import { Icon } from './Icon';
import BodyInspector from './BodyInspector';
import { modalOpen } from './useModal';

// The add-body dialog is core-owned (src/ui/AddBodyDialog.tsx); a glob keeps the sandbox building if it is absent.
type AddModule = { AddBodyDialog?: ComponentType<{ presetId?: string; onClose: () => void }>; default?: ComponentType<{ presetId?: string; onClose: () => void }> };
const addModules = import.meta.glob<AddModule>('./AddBodyDialog.tsx');
const AddBodyDialog = lazy(async () => {
  const load = addModules['./AddBodyDialog.tsx'];
  const mod = load ? await load() : null;
  return { default: mod?.AddBodyDialog ?? mod?.default ?? ((_props: { presetId?: string; onClose: () => void }) => null) };
});

const QUICK_WORLDS = ['real.solar_system', 'real.trappist_1', 'real.kepler_16', 'real.alpha_centauri_ab', 'real.hr_8799', 'generated.binary_p', 'real.sgr_a_s2', 'generated.moon_lab'];

function isTypingTarget(el: EventTarget | null): boolean {
  const e = el as HTMLElement | null;
  if (!e) return false;
  const tag = e.tagName;
  return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || e.isContentEditable;
}

function EmptyState({ onWorlds, onOpen }: { onWorlds: () => void; onOpen: (id: string) => void }) {
  const t = useT();
  const lang = useLang();
  const [auto, setAuto] = useState<SaveRecord | null>(null);
  const loading = useStore(sessionStore, (s) => s.loadingSceneId);
  const autosave = useStore(settingsStore, (s) => s.autosave);
  useEffect(() => {
    void readAutosave().then(setAuto);
  }, []);
  return (
    <div className="empty-state">
      <div className="empty-card">
        <p className="eyebrow">{t('nav.sandbox')}</p>
        <h1>{t('sandbox.chooseWorld')}</h1>
        <p className="muted">{t('sandbox.chooseLead')}</p>
        <p className="faint small">{autosave ? t('sandbox.autosaveOn') : t('sandbox.autosaveOff')}</p>
        <div className="empty-actions">
          <button type="button" className="btn btn-primary btn-lg" disabled={!!loading} onClick={() => onOpen('real.solar_system')}>
            {loading === 'real.solar_system' ? <span className="spinner" /> : <Icon name="play" />}
            {t('sandbox.startSolar')}
          </button>
          {auto && (
            <button type="button" className="btn btn-lg" disabled={!!loading} onClick={() => void loadSaveRecord(auto)}>
              <Icon name="reset" />
              <span className="btn-two-line">
                <span>{t('sandbox.resume')}</span>
                <span className="faint small">{t('sandbox.resumeLead', { scene: tx(auto.sceneName ?? undefined, lang) || auto.sceneId, when: formatRelativeTime(auto.savedAt, lang) })}</span>
              </span>
            </button>
          )}
        </div>
        <div className="quick-worlds">
          {QUICK_WORLDS.map((id) => {
            const e = CATALOG_INDEX.scenes.find((s) => s.id === id);
            if (!e) return null;
            return (
              <button key={id} type="button" className="quick-world" disabled={!!loading} onClick={() => onOpen(id)}>
                <span className="quick-world-name">
                  {tx(e.name, lang)}
                  {loading === id && <span className="spinner" />}
                </span>
                <span className="quick-world-meta">{tx(e.groupLabel, lang)}</span>
              </button>
            );
          })}
          <button type="button" className="quick-world more" onClick={onWorlds}>
            <span className="quick-world-name">{t('library.tab.worlds')}</span>
            <span className="quick-world-meta">{CATALOG_INDEX.counts.scenes}</span>
          </button>
        </div>
      </div>
    </div>
  );
}

export function SandboxPage({ route }: { route: Route }) {
  const t = useT();
  const lang = useLang();
  const s = useStore(sessionStore, (x) => x);
  const world = currentWorld(s);
  const live = !!s.snapshot;
  const selectedBody = bodyOf(s.selection, s.snapshot) ?? (s.preview && s.selection ? s.preview.bodies.find((b) => b.id === s.selection!.id) ?? null : null);
  const [leftTab, setLeftTab] = useState<LeftTab>('bodies');
  const [leftOpen, setLeftOpen] = useState(() => window.matchMedia('(min-width: 1101px)').matches);
  const [rightOpen, setRightOpen] = useState(() => window.matchMedia('(min-width: 761px)').matches);
  const [savesOpen, setSavesOpen] = useState(false);
  const [menu, setMenu] = useState<'view' | 'help' | 'more' | null>(null);
  const [addOpen, setAddOpen] = useState<{ presetId?: string } | null>(null);
  const [gridLabel, setGridLabel] = useState('');
  const [camera, setCamera] = useState<CameraRequest | undefined>(undefined);
  const units = useStore(settingsStore, (x) => x.units);

  // Engine and autosave live while the sandbox is open; playback stops when leaving.
  useEffect(() => {
    void ensureEngine();
    const stopAutosave = startAutosave();
    return () => {
      stopAutosave();
      void pause();
    };
  }, []);

  // Camera requests from the session (focus, fit after loads).
  useEffect(() => {
    if (!s.focusSerial) return;
    setCamera((c) => ({ serial: (c?.serial ?? 0) + 1, id: sessionStore.get().focus?.id ?? null, fit: false }));
  }, [s.focusSerial]);
  useEffect(() => {
    if (!s.fitSerial) return;
    const st = sessionStore.get();
    setCamera((c) => ({ serial: (c?.serial ?? 0) + 1, id: null, fit: true, hint: st.scene?.camera }));
  }, [s.fitSerial]);

  const openWorld = useCallback(
    async (id: string) => {
      if (!(await confirmReplace())) return;
      const ok = await openCatalogueScene(id);
      if (ok && window.matchMedia('(max-width: 1100px)').matches) setLeftOpen(false);
    },
    [t, lang],
  );

  // Route requests: #/sandbox?scene=<id> opens a world; #/sandbox?preset=<id> opens the add dialog with a preset.
  useEffect(() => {
    const sceneParam = route.params.get('scene');
    const presetParam = route.params.get('preset');
    const cosmosParam = route.params.get('cosmos');
    if (!sceneParam && !presetParam && !cosmosParam) return;
    navigate('/sandbox', { replace: true });
    void (async () => {
      if (cosmosParam) {
        // A generated (or observed) system by address: built first, then the same replace guard as everything else.
        let c: Cosmos;
        try {
          c = await loadCosmos();
        } catch {
          notify(t('uni.modelMissing'), 'error');
          return;
        }
        const r = c.resolve(cosmosParam);
        if (!r.ok) {
          notify(t('uni.addressInvalid', { reason: r.message }), 'error');
          return;
        }
        await enterStarSystem(c, r.star);
        return;
      }
      if (sceneParam && sceneParam !== sessionStore.get().scene?.id) await openWorld(sceneParam);
      else if (sceneParam && !currentWorld(sessionStore.get())) await openCatalogueScene(sceneParam);
      if (presetParam) {
        if (!currentWorld(sessionStore.get())) await openCatalogueScene('real.solar_system');
        setAddOpen({ presetId: presetParam });
      }
    })();
  }, [route.serial]); // eslint-disable-line react-hooks/exhaustive-deps

  const deleteSelected = useCallback(async () => {
    const st = sessionStore.get();
    const b = bodyOf(st.selection, st.snapshot);
    if (!b || !st.selection || st.pending) return;
    const shown = bodyDisplayName(b, settingsStore.get().lang, st.scene, st.snapshot, st.appearance);
    const choice = await askConfirm({ title: t('inspector.deleteBody'), body: shown, confirm: t('common.delete'), cancel: t('common.cancel'), danger: true });
    if (choice === 'confirm') await removeBody(st.selection, t('tool.delete') + ': ' + shown);
  }, [t]);

  const doReset = useCallback(async () => {
    const st = sessionStore.get();
    if (!st.scene || st.pending) return;
    const choice = await askConfirm({
      title: t('sandbox.resetTitle'),
      body: t('sandbox.resetBody', { scene: tx(st.scene.name, lang) || st.scene.id }),
      confirm: t('tool.reset'),
      cancel: t('common.cancel'),
      danger: true,
    });
    if (choice === 'confirm') await resetWorld();
  }, [t, lang]);

  // Keyboard shortcuts (ignored while typing or while a dialog is open).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (isTypingTarget(e.target) || e.defaultPrevented) return;
      if (modalOpen() || document.querySelector('.modal-backdrop, .drawer-backdrop, [role="dialog"][aria-modal="true"], [role="alertdialog"][aria-modal="true"]')) return;
      const k = e.key;
      const mod = e.ctrlKey || e.metaKey;
      if (mod && (k === 'z' || k === 'Z')) {
        e.preventDefault();
        void (e.shiftKey ? redo() : undo());
        return;
      }
      if (mod && (k === 'y' || k === 'Y')) {
        e.preventDefault();
        void redo();
        return;
      }
      if (mod || e.altKey) return;
      switch (k) {
        case ' ':
          e.preventDefault();
          togglePlay();
          break;
        case '.':
          void stepOnce();
          break;
        case '[':
          nudgeRate(-1);
          break;
        case ']':
          nudgeRate(1);
          break;
        case 'f':
        case 'F': {
          const st = sessionStore.get();
          if (st.selection) focusBody(st.selection.id);
          break;
        }
        case 'h':
        case 'H':
          requestFit();
          break;
        case 'Delete':
        case 'Backspace':
          void deleteSelected();
          break;
        case 'l':
        case 'L':
          setSetting('showLabels', !settingsStore.get().showLabels);
          break;
        case 'o':
        case 'O':
          setSetting('showOrbits', !settingsStore.get().showOrbits);
          break;
        case 't':
        case 'T':
          setSetting('showTrails', !settingsStore.get().showTrails);
          break;
        case 'g':
        case 'G':
          setSetting('showGrid', !settingsStore.get().showGrid);
          break;
        case 'Escape':
          setMenu(null);
          selectBody(null);
          break;
        default:
          return;
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [deleteSelected]);

  const onGridScale = useCallback(
    (m: number) => {
      setGridLabel(formatQuantity('distance', m, lang, units, 2));
    },
    [lang, units],
  );

  const pending = s.pending;
  const history = s.snapshot?.history;
  const sceneName = tx(s.scene?.name, lang) || s.scene?.id || '';
  const canEdit = live && !pending;
  const showEmpty = !world && !s.loadingSceneId;

  return (
    <div className={'sandbox' + (leftOpen ? ' left-open' : '') + (rightOpen ? ' right-open' : '')}>
      <div className="sb-view">
        <Viewport
          source={sandboxSource}
          interactive
          camera={camera}
          onPick={(id) => {
            selectBody(id);
            if (id !== null && window.matchMedia('(max-width: 760px)').matches) setRightOpen(true);
          }}
          onFocus={(id) => {
            selectBody(id);
            focusBody(id);
          }}
          onGridScale={onGridScale}
        />
        {world && s.engineStatus !== 'unavailable' && gridLabel && (
          <div className="grid-hud" aria-hidden="true">
            <span className="grid-hud-ring" />
            {gridLabel}
          </div>
        )}
        {s.engineStatus === 'unavailable' && (
          <div className="view-banner danger" role="alert">
            <Icon name="warning" size={18} />
            <span>{t('engine.unavailableBody', { reason: s.engineError ?? '' })}</span>
            <button type="button" className="btn btn-sm" onClick={retryEngine}>
              {t('engine.retry')}
            </button>
          </div>
        )}
        {s.loadingSceneId && (
          <div className="view-loading" role="status">
            <span className="spinner" />
            {t('sandbox.loadingWorld', { scene: tx(CATALOG_INDEX.scenes.find((x) => x.id === s.loadingSceneId)?.name, lang) || s.loadingSceneId })}
          </div>
        )}
        {showEmpty && (
          <EmptyState
            onOpen={(id) => void openWorld(id)}
            onWorlds={() => {
              setLeftTab('worlds');
              setLeftOpen(true);
            }}
          />
        )}
      </div>

      <header className="sb-bar">
        <div className="sb-bar-left">
          <button type="button" className="icon-btn panel-toggle" onClick={() => setLeftOpen((v) => !v)} aria-pressed={leftOpen} title={t('sandbox.bodies')} aria-label={t('sandbox.bodies')}>
            <Icon name="layers" />
          </button>
          <button
            type="button"
            className="world-title"
            onClick={() => {
              setLeftTab('worlds');
              setLeftOpen(true);
            }}
            title={t('sandbox.worlds')}
          >
            <span className="world-title-name">{sceneName || t('sandbox.chooseWorld')}</span>
            <Icon name="chevronDown" size={16} />
          </button>
          <WorldStatusChip />
          {pending && (
            <span className="pending-chip" role="status">
              <span className="spinner" />
              {t('sandbox.pending', { what: pending.label })}
            </span>
          )}
        </div>
        <div className="sb-tools" role="toolbar" aria-label={t('tool.add')}>
          <button type="button" className="tool-btn primary" disabled={!canEdit} onClick={() => setAddOpen({})} title={live ? t('tool.add') : t('add.needsWorld')}>
            <Icon name="plus" />
            <span className="tool-label">{t('tool.add')}</span>
          </button>
          <button type="button" className="tool-btn" disabled={!canEdit || !selectedBody} onClick={() => void deleteSelected()} title={t('tool.delete') + ' (Delete)'}>
            <Icon name="trash" />
          </button>
          <span className="tool-sep tool-secondary" />
          <button
            type="button"
            className="tool-btn tool-secondary"
            disabled={!canEdit || !history?.canUndo}
            onClick={() => void undo()}
            title={history?.canUndo ? t('tool.undoLabel', { label: history.undoLabel }) + ' (Ctrl+Z)' : t('tool.nothingUndo')}
            aria-label={t('tool.undo')}
          >
            <Icon name="undo" />
          </button>
          <button
            type="button"
            className="tool-btn tool-secondary"
            disabled={!canEdit || !history?.canRedo}
            onClick={() => void redo()}
            title={history?.canRedo ? t('tool.redoLabel', { label: history.redoLabel }) + ' (Ctrl+Shift+Z)' : t('tool.nothingRedo')}
            aria-label={t('tool.redo')}
          >
            <Icon name="redo" />
          </button>
          <button type="button" className="tool-btn tool-secondary" disabled={!canEdit || !s.scene} onClick={() => void doReset()} title={t('tool.reset')} aria-label={t('tool.reset')}>
            <Icon name="reset" />
          </button>
          <span className="tool-sep tool-secondary" />
          <button type="button" className="tool-btn tool-secondary" disabled={!world} onClick={requestFit} title={t('tool.fit') + ' (H)'} aria-label={t('tool.fit')}>
            <Icon name="fit" />
          </button>
          <div className="anchor more-anchor" data-popover-anchor>
            <button
              type="button"
              className={'tool-btn more-btn' + (menu === 'more' ? ' active' : '')}
              onClick={() => setMenu(menu === 'more' ? null : 'more')}
              aria-expanded={menu === 'more'}
              aria-haspopup="menu"
              title={t('tool.more')}
              aria-label={t('tool.more')}
            >
              <Icon name="more" />
            </button>
          </div>
        </div>
        <div className="sb-bar-right">
          <button type="button" className="tool-btn map-btn" onClick={() => navigate(mapRouteFor(s.location))} title={s.location ? t('uni.backToMap') : t('nav.universe')}>
            <Icon name="galaxy" />
            <span className="tool-label">{t('uni.mapShort')}</span>
          </button>
          <button type="button" className="tool-btn saves-btn" onClick={() => setSavesOpen(true)} title={t('tool.saves')}>
            <Icon name="save" />
            <span className="tool-label">{t('tool.saves')}</span>
          </button>
          <div className="anchor" data-popover-anchor>
            <button type="button" className={'tool-btn' + (menu === 'view' ? ' active' : '')} onClick={() => setMenu(menu === 'view' ? null : 'view')} aria-expanded={menu === 'view'} title={t('tool.view')}>
              <Icon name="eye" />
              <span className="tool-label">{t('tool.view')}</span>
            </button>
          </div>
          <div className="anchor help-anchor" data-popover-anchor>
            <button type="button" className={'tool-btn' + (menu === 'help' ? ' active' : '')} onClick={() => setMenu(menu === 'help' ? null : 'help')} aria-expanded={menu === 'help'} title={t('tool.help')} aria-label={t('tool.help')}>
              <Icon name="help" />
            </button>
          </div>
          <button type="button" className="icon-btn panel-toggle" onClick={() => setRightOpen((v) => !v)} aria-pressed={rightOpen} title={t('inspector.title')} aria-label={t('inspector.title')}>
            <Icon name="info" />
          </button>
        </div>
        {menu === 'view' && <ViewMenu onClose={() => setMenu(null)} />}
        {menu === 'help' && <HelpMenu onClose={() => setMenu(null)} />}
        {menu === 'more' && (
          <ActionsMenu
            onClose={() => setMenu(null)}
            pending={pending?.label ?? null}
            canUndo={canEdit && !!history?.canUndo}
            canRedo={canEdit && !!history?.canRedo}
            undoLabel={history?.canUndo ? history.undoLabel : ''}
            redoLabel={history?.canRedo ? history.redoLabel : ''}
            canReset={canEdit && !!s.scene}
            canFit={!!world}
            onUndo={() => void undo()}
            onRedo={() => void redo()}
            onReset={() => {
              setMenu(null);
              void doReset();
            }}
            onFit={() => {
              setMenu(null);
              requestFit();
            }}
            onHelp={() => setMenu('help')}
            mapLabel={s.location ? t('uni.backToMap') : t('nav.universe')}
            onMap={() => {
              setMenu(null);
              navigate(mapRouteFor(s.location));
            }}
            onSaves={() => {
              setMenu(null);
              setSavesOpen(true);
            }}
          />
        )}
      </header>

      {leftOpen && (
        <LeftPanel
          tab={leftTab}
          onTab={setLeftTab}
          onOpenWorld={(id) => void openWorld(id)}
          onClose={() => setLeftOpen(false)}
        />
      )}

      {rightOpen && (
        <div className="sb-right">
          {selectedBody ? <BodyInspector onClose={() => selectBody(null)} /> : <WorldOverview />}
          <button type="button" className="icon-btn sheet-close" onClick={() => setRightOpen(false)} aria-label={t('common.close')}>
            <Icon name="close" />
          </button>
        </div>
      )}

      <footer className="sb-time">
        <TimeBar />
      </footer>

      {savesOpen && <SavesPanel onClose={() => setSavesOpen(false)} />}
      {addOpen && (
        <Suspense fallback={null}>
          <AddBodyDialog presetId={addOpen.presetId} onClose={() => setAddOpen(null)} />
        </Suspense>
      )}
    </div>
  );
}

export default SandboxPage;
