// AiXenix Cosmos Lab web client: sandbox left panel: the bodies of the current world and the world picker.

import { useMemo, useState } from 'react';
import type { EngineBody } from '../../engine/types';
import { useLang, useT } from '../../app/settings';
import { useStore } from '../../app/store';
import { currentWorld, focusBody, sameIdentity, selectBody, sessionStore } from '../../app/session';
import { formatQuantity } from '../../app/units';
import { searchCatalog, SCENE_KIND_ORDER, tx, type SceneIndexEntry } from '../../content/catalog';
import { CATALOG_INDEX } from '../../content/catalog.generated';
import { classLabel } from '../../content/strings';
import { displayNames } from '../../app/names';
import { resolveLook, lookColor } from '../../render/appearance';
import { settingsStore } from '../../app/settings';
import { Icon } from '../Icon';

export type LeftTab = 'bodies' | 'worlds';

function BodyRow({ body, name, depth, selected, color }: { body: EngineBody; name: string; depth: number; selected: boolean; color: string }) {
  const lang = useLang();
  const units = useStore(settingsStore, (s) => s.units);
  return (
    <li>
      <div
        className={'body-row' + (selected ? ' selected' : '')}
        style={{ paddingLeft: 10 + depth * 16 }}
        role="button"
        tabIndex={0}
        aria-pressed={selected}
        onClick={() => selectBody(body.id)}
        onDoubleClick={() => focusBody(body.id)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') selectBody(body.id);
        }}
      >
        <span className="body-dot" style={{ background: color }} aria-hidden="true" />
        <span className="body-name">{name}</span>
        <span className="body-meta">
          {classLabel(body.classTag || body.kind, lang)} · {formatQuantity('mass', body.mass, lang, units, 3)}
        </span>
        <button
          type="button"
          className="icon-btn xs"
          onClick={(e) => {
            e.stopPropagation();
            selectBody(body.id);
            focusBody(body.id);
          }}
          title="F"
          aria-label="Focus"
        >
          <Icon name="focus" size={15} />
        </button>
      </div>
    </li>
  );
}

function BodiesList() {
  const t = useT();
  const world = useStore(sessionStore, currentWorld);
  const selection = useStore(sessionStore, (s) => s.selection);
  const appearance = useStore(sessionStore, (s) => s.appearance);
  const scene = useStore(sessionStore, (s) => s.scene);
  const lang = useLang();
  const names = useMemo(() => (world ? displayNames(world, lang, scene, appearance) : {}), [world, lang, scene, appearance]);
  const [q, setQ] = useState('');
  const rows = useMemo(() => {
    if (!world) return [];
    const ids = new Set(world.bodies.map((b) => b.id));
    const children = new Map<number, EngineBody[]>();
    const roots: EngineBody[] = [];
    for (const b of world.bodies) {
      if (b.parentId && ids.has(b.parentId) && b.parentId !== b.id) {
        const arr = children.get(b.parentId) ?? [];
        arr.push(b);
        children.set(b.parentId, arr);
      } else roots.push(b);
    }
    const out: { body: EngineBody; depth: number }[] = [];
    const seen = new Set<number>();
    const walk = (b: EngineBody, depth: number) => {
      if (seen.has(b.id)) return;
      seen.add(b.id);
      out.push({ body: b, depth });
      for (const c of (children.get(b.id) ?? []).sort((x, y) => y.mass - x.mass)) walk(c, depth + 1);
    };
    roots.sort((x, y) => y.mass - x.mass).forEach((r) => walk(r, 0));
    for (const b of world.bodies) if (!seen.has(b.id)) walk(b, 0);
    return out;
  }, [world]);
  const colors = useMemo(() => {
    const m = new Map<number, string>();
    if (!world) return m;
    for (const b of world.bodies) {
      const c = lookColor(resolveLook(b, appearance[b.key]));
      m.set(b.id, `rgb(${Math.round(c[0] * 255)}, ${Math.round(c[1] * 255)}, ${Math.round(c[2] * 255)})`);
    }
    return m;
  }, [world?.worldId, world?.historyRevision, world?.bodies.length, appearance]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!world) return <p className="panel-empty muted">{t('sandbox.world.none')}</p>;
  const ql = q.trim().toLowerCase();
  const filtered = ql ? rows.filter((r) => ((names[r.body.id] ?? r.body.name) + ' ' + r.body.name + ' ' + r.body.key).toLowerCase().includes(ql)) : rows;
  const selId = selection && (sameIdentity(selection, world) || world.worldId === -1) ? selection.id : null;
  return (
    <div className="panel-section">
      <div className="search-box sm">
        <Icon name="search" size={16} />
        <input className="input" placeholder={t('sandbox.searchBodies')} value={q} onChange={(e) => setQ(e.target.value)} aria-label={t('sandbox.searchBodies')} />
      </div>
      <ul className="body-list">
        {filtered.map((r) => (
          <BodyRow key={r.body.id} body={r.body} name={names[r.body.id] ?? r.body.name} depth={ql ? 0 : r.depth} selected={r.body.id === selId} color={colors.get(r.body.id) ?? '#9ab'} />
        ))}
      </ul>
    </div>
  );
}

function WorldsList({ onOpen }: { onOpen: (id: string) => void }) {
  const t = useT();
  const lang = useLang();
  const [q, setQ] = useState('');
  const current = useStore(sessionStore, (s) => s.scene?.id ?? null);
  const loading = useStore(sessionStore, (s) => s.loadingSceneId);
  const pending = useStore(sessionStore, (s) => s.pending);
  const groups = useMemo(() => {
    const hits = q.trim() ? new Set(searchCatalog(CATALOG_INDEX, q, lang, 100).filter((h) => h.type === 'scene').map((h) => h.id)) : null;
    const out: { kind: string; label: string; items: SceneIndexEntry[] }[] = [];
    for (const kind of SCENE_KIND_ORDER) {
      const items = CATALOG_INDEX.scenes.filter((s) => s.kind === kind && (!hits || hits.has(s.id)));
      if (items.length) out.push({ kind, label: tx(CATALOG_INDEX.labels.sceneKinds[kind], lang) || kind, items });
    }
    return out;
  }, [q, lang]);
  return (
    <div className="panel-section">
      <div className="search-box sm">
        <Icon name="search" size={16} />
        <input className="input" placeholder={t('sandbox.searchWorlds')} value={q} onChange={(e) => setQ(e.target.value)} aria-label={t('sandbox.searchWorlds')} />
      </div>
      {groups.length === 0 && <p className="panel-empty muted">{t('common.noResults', { q })}</p>}
      {groups.map((g) => (
        <div key={g.kind} className="world-group">
          <p className="world-group-title">{g.label}</p>
          <ul className="world-list">
            {g.items.map((s) => (
              <li key={s.id}>
                <button
                  type="button"
                  className={'world-row' + (s.id === current ? ' current' : '')}
                  disabled={!!pending}
                  onClick={() => onOpen(s.id)}
                  aria-current={s.id === current ? 'true' : undefined}
                >
                  <span className="world-row-name">
                    {tx(s.name, lang)}
                    {loading === s.id && <span className="spinner" />}
                  </span>
                  <span className="world-row-meta">
                    {tx(s.groupLabel, lang)} · {t('library.bodies', { n: s.bodyCount })}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  );
}

export function LeftPanel({ tab, onTab, onOpenWorld, onClose }: { tab: LeftTab; onTab: (t: LeftTab) => void; onOpenWorld: (id: string) => void; onClose?: () => void }) {
  const t = useT();
  return (
    <div className="panel left-panel">
      <div className="panel-head">
        <div className="panel-tabs" role="tablist">
          <button type="button" role="tab" aria-selected={tab === 'bodies'} className={tab === 'bodies' ? 'active' : ''} onClick={() => onTab('bodies')}>
            {t('sandbox.bodies')}
          </button>
          <button type="button" role="tab" aria-selected={tab === 'worlds'} className={tab === 'worlds' ? 'active' : ''} onClick={() => onTab('worlds')}>
            {t('sandbox.worlds')}
          </button>
        </div>
        {onClose && (
          <button type="button" className="icon-btn panel-close" onClick={onClose} aria-label={t('common.close')}>
            <Icon name="close" />
          </button>
        )}
      </div>
      <div className="panel-body">{tab === 'bodies' ? <BodiesList /> : <WorldsList onOpen={onOpenWorld} />}</div>
    </div>
  );
}
