// AiXenix Cosmos Lab web client: the right panel when no body is selected. Player-facing first: what this world is,
// what the engine computes, how far to trust it, where the data comes from and how it is kept. Engine diagnostics
// (profile, step, energy error, state hash, raw catalogue notes) sit in a collapsed section.

import { useEffect, useState } from 'react';
import { useLang, useSetting, useT } from '../../app/settings';
import { loadCosmos, cosmosAvailable } from '../../app/cosmos';
import { mapRouteFor } from '../../app/universe';
import { navigate } from '../../app/router';
import { useStore } from '../../app/store';
import { currentWorld, isDirty, isEdited, retryEngine, sessionStore } from '../../app/session';
import { href } from '../../app/router';
import { formatNumber, formatQuantity, formatSpan } from '../../app/units';
import { settingsStore } from '../../app/settings';
import { SIMULATION_LABEL, tx } from '../../content/catalog';
import { CATALOG_INDEX } from '../../content/catalog.generated';
import { tr } from '../../content/strings';
import { Icon } from '../Icon';

export function WorldStatusChip() {
  const t = useT();
  const s = useStore(sessionStore, (x) => x);
  const autosave = useSetting('autosave');
  const dirty = isDirty(s);
  const edited = isEdited(s);
  if (!s.snapshot && !s.preview) return <span className="world-chip-status">{t('sandbox.world.none')}</span>;
  if (!s.snapshot) return <span className="world-chip-status warn">{t('sandbox.world.preview')}</span>;
  let text: string;
  let tone = '';
  if (dirty) {
    text = edited ? t('sandbox.world.edited') : t('sandbox.world.advanced');
    tone = 'warn';
  } else if (s.origin?.kind === 'save' || (s.savedName && s.origin?.kind !== 'import')) text = s.savedName ? t('sandbox.world.saved', { name: s.savedName }) : t('sandbox.world.fresh');
  else if (s.origin?.kind === 'import' || s.origin?.kind === 'scene-file') text = t('sandbox.world.imported', { file: s.origin.file });
  else if (s.origin?.kind === 'cosmos') text = t('sandbox.world.generated');
  else text = t('sandbox.world.fresh');
  if (!dirty && s.savedName) tone = 'ok';
  return (
    <span className={'world-chip-status ' + tone} title={autosave ? t('sandbox.world.ownershipAuto') : t('sandbox.world.ownershipManual')}>
      {text}
    </span>
  );
}

function LocationBlock() {
  const t = useT();
  const lang = useLang();
  const loc = useStore(sessionStore, (x) => x.location);
  const [galaxy, setGalaxy] = useState<string | null>(null);
  useEffect(() => {
    if (!loc || !cosmosAvailable()) return;
    let live = true;
    loadCosmos()
      .then((c) => {
        if (!live) return;
        const info = c.galaxyInfo(loc.galaxyId);
        setGalaxy(tx(info?.name, lang) || tx(c.summary(loc.galaxyId)?.name, lang) || loc.galaxyId);
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, [loc, lang]);
  if (!loc) return null;
  return (
    <div className="callout location">
      <Icon name="galaxy" size={18} />
      <div>
        <p className="callout-title">{t('uni.locationTitle')}</p>
        <p className="muted small">
          {galaxy ?? loc.galaxyId} · {loc.provenance === 'procedural' ? t('uni.legend.procedural').split(':')[0] : t('uni.legend.observed').split(':')[0]}
        </p>
        <p className="num small loc-address">{loc.address}</p>
        {loc.provenance === 'procedural' && <p className="faint small">{t('uni.generated')}</p>}
        <button type="button" className="btn btn-sm" onClick={() => navigate(mapRouteFor(loc))}>
          {t('uni.showOnMap')}
        </button>
      </div>
    </div>
  );
}

export function WorldOverview() {
  const t = useT();
  const lang = useLang();
  const units = useStore(settingsStore, (s) => s.units);
  const autosave = useSetting('autosave');
  const s = useStore(sessionStore, (x) => x);
  const world = currentWorld(s);
  const scene = s.scene;
  if (!world || !scene) {
    return (
      <div className="panel right-panel overview">
        <div className="panel-body">
          <p className="panel-empty muted">{t('inspector.empty')}</p>
        </div>
      </div>
    );
  }
  const entry = CATALOG_INDEX.scenes.find((e) => e.id === scene.id);
  const totalMass = world.bodies.reduce((a, b) => a + b.mass, 0);
  const sources = scene.sources ?? [];
  const catalogueNote = tx(scene.validation?.status_text, lang);
  return (
    <div className="panel right-panel overview">
      <div className="panel-head">
        <div>
          <p className="eyebrow">{t('inspector.world')}</p>
          <h2 className="panel-title">{tx(scene.name, lang) || scene.id}</h2>
        </div>
      </div>
      <div className="panel-body">
        {s.engineStatus === 'unavailable' && (
          <div className="callout danger">
            <Icon name="warning" size={18} />
            <div>
              <p>{t('engine.unavailableBody', { reason: s.engineError ?? '' })}</p>
              <button type="button" className="btn btn-sm" onClick={retryEngine}>
                {t('engine.retry')}
              </button>
            </div>
          </div>
        )}
        <p className="muted">{tx(scene.description, lang)}</p>
        {s.location && <LocationBlock />}
        {entry && (
          <p className="overview-kind faint">
            {tx(entry.kindLabel, lang)} · {tx(entry.groupLabel, lang)}
          </p>
        )}

        <dl className="kv">
          <div>
            <dt>{t('inspector.overview.bodies')}</dt>
            <dd className="num">{world.bodies.length}</dd>
          </div>
          <div>
            <dt>{t('inspector.overview.mass')}</dt>
            <dd className="num">{formatQuantity('mass', totalMass, lang, units)}</dd>
          </div>
          <div>
            <dt>{t('inspector.overview.epoch')}</dt>
            <dd>{scene.epoch?.label ?? '—'}</dd>
          </div>
          <div>
            <dt>{t('inspector.overview.mode')}</dt>
            <dd>{tx(SIMULATION_LABEL, lang)}</dd>
          </div>
        </dl>

        <div className="callout">
          <Icon name="info" size={18} />
          <div>
            <p className="callout-title">{t('inspector.overview.validity')}</p>
            <p className="muted">{tr('sim.tip', lang)}</p>
            <p className="muted">{tr('catalogue.not_validated', lang)}</p>
            <a className="callout-link" href={href('/handbook/physics')}>
              {t('inspector.overview.modelLink')}
              <Icon name="chevronRight" size={14} />
            </a>
          </div>
        </div>

        {sources.length > 0 && (
          <div className="sources">
            <p className="eyebrow">{t('inspector.overview.sources')}</p>
            <ul>
              {sources.slice(0, 8).map((src) => (
                <li key={src.id}>
                  {src.url ? (
                    <a href={src.url} target="_blank" rel="noreferrer">
                      {src.title || src.id}
                      <Icon name="external" size={13} />
                    </a>
                  ) : (
                    src.title || src.id
                  )}
                </li>
              ))}
            </ul>
          </div>
        )}

        <p className="ownership faint">
          <Icon name="save" size={15} /> {autosave ? t('sandbox.world.ownershipAuto') : t('sandbox.world.ownershipManual')}
        </p>

        <details className="advanced">
          <summary>{t('inspector.overview.advanced')}</summary>
          <dl className="kv">
            {s.snapshot && (
              <>
                <div>
                  <dt>{t('time.baseStep')}</dt>
                  <dd className="num">{formatSpan(s.snapshot.baseStep, lang, 4)}</dd>
                </div>
                <div>
                  <dt>{t('inspector.overview.profile')}</dt>
                  <dd className="num">{s.snapshot.profile}</dd>
                </div>
                <div>
                  <dt>{t('time.energy')}</dt>
                  <dd className="num">{formatNumber(s.snapshot.conservation.relativeEnergyError, lang, 3)}</dd>
                </div>
                <div>
                  <dt>{t('inspector.overview.hash')}</dt>
                  <dd className="num hash">{s.snapshot.stateHash}</dd>
                </div>
              </>
            )}
          </dl>
          {catalogueNote && (
            <p className="faint small">
              <span className="advanced-label">{t('inspector.overview.catalogueNote')}:</span> {catalogueNote}
            </p>
          )}
          {s.issues.length > 0 && (
            <div className="advanced-issues">
              <p className="advanced-label">{t('inspector.overview.loadNotes')}</p>
              <ul className="issues">
                {s.issues.slice(0, 6).map((i, k) => (
                  <li key={k}>
                    <code>{i.path}</code> {i.message}
                  </li>
                ))}
              </ul>
            </div>
          )}
        </details>
        <p className="faint small">{t('inspector.empty')}</p>
      </div>
    </div>
  );
}
