// AiXenix Cosmos Lab web client: the body inspector (properties, orbit, source data) with its edit dialog and deletion.
// Every value shown is the engine's current state (SI inside; display units only here). An edit is bound to the world it
// was opened in: (worldId, historyRevision, id). If the world changed since (Undo, Redo, load, switch) the edit is refused
// instead of being applied to another body.

import { useCallback, useEffect, useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import type { EngineBody, EngineSnapshot, BodyPatch, Vec3 } from '../engine/types';
import { tx, type Lang, type LocalizedText, type SceneBody, type SceneFile } from '../content/catalog';
import { classLabel } from '../content/strings';
import { useStore } from '../app/store';
import { useLang, useSetting, useT, type TFunction } from '../app/settings';
import { askConfirm, notify } from '../app/notices';
import {
  bodyOf,
  currentWorld,
  editBody,
  focusBody,
  removeBody,
  sameIdentity,
  sessionStore,
  type BodyRef,
} from '../app/session';
import { osculating, primaryOf, len } from '../app/astro';
import { autoUnit, formatNumber, formatQuantity, formatSpan, inputText, unitById, unitLabel, type Quantity } from '../app/units';
import { lookColor, resolveLook } from '../render/appearance';
import { QuantityField, VectorField, validateField, type FieldRule } from './controls';
import { Icon } from './Icon';
import { bodyDisplayName } from '../app/names';

// The shared naming rule (tree, canvas labels, notices and this inspector use one implementation).
export { bodyDisplayName };
import '../styles/inspector.css';

