type LocalKey = keyof typeof S;

function useL(): (key: LocalKey, vars?: Record<string, string | number>) => string {
  const lang = useLang();
  return useCallback(
    (key: LocalKey, vars?: Record<string, string | number>) => {
      let text = tx(S[key], lang);
      if (vars) text = text.replace(/\{(\w+)\}/g, (m, name: string) => (name in vars ? String(vars[name]) : m));
      return text;
    },
    [lang],
  );
}

// ---- helpers --------------------------------------------------------------------------------------------------------

const C = 299792458; // m/s
const HOLE_KINDS = new Set(['black_hole', 'agn']);
const COMPACT_KINDS = new Set(['black_hole', 'agn', 'neutron_star', 'pulsar']);

/** Stops keys typed inside the inspector from reaching the page's global shortcuts (space, arrows, Delete...). */
function stopKeys(e: KeyboardEvent<HTMLElement>): void {
  const el = e.target as HTMLElement;
  if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement || el instanceof HTMLTextAreaElement || el.isContentEditable) {
    e.stopPropagation();
  }
}

function sceneEntry(scene: SceneFile | null, world: EngineSnapshot | null, key: string): { body: SceneBody; optional: boolean } | null {
  if (!scene || !world || !key || scene.id !== world.sceneId) return null;
  const main = scene.bodies.find((b) => b.id === key);
  if (main) return { body: main, optional: false };
  const opt = scene.optional_bodies?.find((b) => b.id === key);
  return opt ? { body: opt, optional: true } : null;
}

function bodyColor(body: EngineBody, appearance: Record<string, unknown>): string {
  try {
    const [r, g, b] = lookColor(resolveLook(body, appearance[body.key] as Parameters<typeof resolveLook>[1]));
    return `rgb(${Math.round(r * 255)}, ${Math.round(g * 255)}, ${Math.round(b * 255)})`;
  } catch {
    return 'var(--accent)';
  }
}

function Row({ label, children, mono }: { label: ReactNode; children: ReactNode; mono?: boolean }) {
  return (
    <div className="bi-row">
      <dt>{label}</dt>
      <dd className={mono ? 'bi-mono' : undefined}>{children}</dd>
    </div>
  );
}

function VecRow({ label, q, v, lang, system }: { label: string; q: Quantity; v: Vec3; lang: Lang; system: 'astro' | 'si' }) {
  const unit = autoUnit(q, Math.max(Math.abs(v[0]), Math.abs(v[1]), Math.abs(v[2])), system);
  return (
    <div className="bi-row bi-vec">
      <dt>
        {label} <span className="bi-unit">{unitLabel(unit, lang)}</span>
      </dt>
      <dd className="bi-mono">
        {(['x', 'y', 'z'] as const).map((axis, i) => (
          <span key={axis} className="bi-vcomp">
            <span className="bi-axis">{axis}</span>
            {formatNumber(v[i]! / unit.factor, lang, 5)}
          </span>
        ))}
      </dd>
    </div>
  );
}

// ---- tabs -----------------------------------------------------------------------------------------------------------

function PropertiesTab({ body, lang, t }: { body: EngineBody; lang: Lang; t: TFunction }) {
  const system = useSetting('units');
  const q = (quantity: Quantity, si: number) => formatQuantity(quantity, si, lang, system);
  const hole = HOLE_KINDS.has(body.kind);
  const density = !hole && body.radius > 0 ? body.mass / ((4 / 3) * Math.PI * body.radius ** 3) : null;
  const flags = (['userEdited', 'controversial', 'fantasyOutcome', 'outsideValidity'] as const).filter((f) => body.flags[f]);
  return (
    <div className="bi-tab">
      <dl className="bi-grid">
        <Row label={t('inspector.mass')}>{q('mass', body.mass)}</Row>
        <Row label={t('inspector.radius')}>{q('radius', body.radius)}</Row>
        {density !== null && (
          <Row label={t('inspector.density')}>
            {formatNumber(density, lang, 4)} {lang === 'ru' ? 'кг/м³' : 'kg/m³'}
          </Row>
        )}
        {COMPACT_KINDS.has(body.kind) && <Row label={t('inspector.schwarzschild')}>{q('radius', body.schwarzschildRadius)}</Row>}
        {body.luminosity > 0 && <Row label={t('inspector.luminosity')}>{q('luminosity', body.luminosity)}</Row>}
        {body.effectiveTemperature > 0 && <Row label={t('inspector.teff')}>{q('temperature', body.effectiveTemperature)}</Row>}
        {body.equilibriumTemperature !== null && body.equilibriumTemperature > 0 && (
          <Row label={t('inspector.teq')}>{q('temperature', body.equilibriumTemperature)}</Row>
        )}
        {body.surfaceTemperature !== null && body.surfaceTemperature > 0 && (
          <Row label={t('inspector.tsurf')}>{q('temperature', body.surfaceTemperature)}</Row>
        )}
        {body.stellarFlux !== null && body.stellarFlux > 0 && <Row label={t('inspector.flux')}>{q('flux', body.stellarFlux)}</Row>}
        <Row label={t('inspector.speed')}>{q('velocity', len(body.velocity))}</Row>
      </dl>
      <h4 className="bi-sub">{t('inspector.state')}</h4>
      <dl className="bi-grid">
        <VecRow label={t('inspector.position')} q="distance" v={body.position} lang={lang} system={system} />
        <VecRow label={t('inspector.velocity')} q="velocity" v={body.velocity} lang={lang} system={system} />
      </dl>
      <p className="bi-note">{t('inspector.frame')}</p>
      {flags.length > 0 && (
        <>
          <h4 className="bi-sub">{t('inspector.flags')}</h4>
          <ul className="bi-flags">
            {flags.map((f) => (
              <li key={f} className={`bi-flag bi-flag-${f}`}>
                {t(`inspector.flag.${f}` as Parameters<TFunction>[0])}
              </li>
            ))}
          </ul>
        </>
      )}
    </div>
  );
}

function OrbitTab({
  body,
  world,
  lang,
  t,
  L,
  nameOf,
}: {
  body: EngineBody;
  world: EngineSnapshot;
  lang: Lang;
  t: TFunction;
  L: ReturnType<typeof useL>;
  nameOf: (b: EngineBody) => string;
}) {
  const system = useSetting('units');
  const byId = useMemo(() => new Map(world.bodies.map((b) => [b.id, b])), [world.bodies]);
  const primary = primaryOf(body, world.bodies, byId);
  if (!primary) return <p className="bi-empty-note">{L('noPrimary')}</p>;
  const el = osculating(body, primary);
  const q = (quantity: Quantity, si: number) => formatQuantity(quantity, si, lang, system);
  return (
    <div className="bi-tab">
      <dl className="bi-grid">
        <Row label={t('inspector.parent')}>
          <button type="button" className="bi-link" onClick={() => focusBody(primary.id)}>
            {nameOf(primary)}
          </button>
        </Row>
        <Row label={t('inspector.distance', { parent: nameOf(primary) })}>{q('distance', len([body.position[0] - primary.position[0], body.position[1] - primary.position[1], body.position[2] - primary.position[2]]))}</Row>
        {el && el.bound && (
          <>
            <Row label={t('inspector.semiMajor')}>{q('distance', el.a)}</Row>
            <Row label={t('inspector.eccentricity')}>{formatNumber(el.e, lang, 4)}</Row>
            <Row label={t('inspector.period')}>{formatSpan(el.period, lang, 4)}</Row>
          </>
        )}
        {el && !el.bound && <Row label={t('inspector.eccentricity')}>{formatNumber(el.e, lang, 4)}</Row>}
      </dl>
      {el && !el.bound && <p className="bi-warn">{t('inspector.unbound', { parent: nameOf(primary) })}</p>}
      <p className="bi-note">{L('osculatingNote', { parent: nameOf(primary) })}</p>
    </div>
  );
}

function SourceTab({ body, world, scene, lang, L }: { body: EngineBody; world: EngineSnapshot; scene: SceneFile | null; lang: Lang; L: ReturnType<typeof useL> }) {
  const entry = sceneEntry(scene, world, body.key);
  const sharing = body.key ? world.bodies.filter((b) => b.key === body.key).length : 1;
  return (
    <div className="bi-tab">
      <dl className="bi-grid">
        <Row label={L('key')} mono>
          {body.key || '—'}
        </Row>
        <Row label={L('id')} mono>
          {body.id}
        </Row>
      </dl>
      {!entry && <p className="bi-note">{L('noSource')}</p>}
      {entry && (
        <>
          {body.flags.userEdited && <p className="bi-warn">{entry.optional ? L('addedNote') : L('editedNote')}</p>}
          {sharing > 1 && <p className="bi-warn">{L('duplicateNote', { n: sharing, key: body.key })}</p>}
          <h4 className="bi-sub">{L('catalogue')}</h4>
          <dl className="bi-grid">
            {entry.body.catalogue_name && <Row label={L('catalogueName')}>{entry.body.catalogue_name}</Row>}
            <Row label={lang === 'ru' ? 'Класс' : 'Class'}>
              {classLabel(entry.body.class, lang)}
              {entry.body.subclass ? ` · ${classLabel(entry.body.subclass, lang, 'subclass')}` : ''}
            </Row>
          </dl>
          {entry.body.flags?.reconstructed_fields && entry.body.flags.reconstructed_fields.length > 0 && (
            <>
              <h4 className="bi-sub">{L('reconstructed')}</h4>
              <p className="bi-mono bi-small">{entry.body.flags.reconstructed_fields.join(', ')}</p>
            </>
          )}
          {entry.body.provenance && Object.keys(entry.body.provenance).length > 0 && (
            <>
              <h4 className="bi-sub">{L('fields')}</h4>
              <ul className="bi-prov">
                {Object.entries(entry.body.provenance).map(([field, p]) => (
                  <li key={field}>
                    <span className="bi-mono bi-prov-field">{field}</span>
                    <span className={`bi-prov-kind bi-prov-${p.kind}`}>{p.kind}</span>
                    {p.source && <span className="bi-prov-source">{p.source}</span>}
                    {(p.method || p.note) && <span className="bi-prov-text">{p.method ?? p.note}</span>}
                  </li>
                ))}
              </ul>
            </>
          )}
          {scene?.sources && scene.sources.length > 0 && (
            <>
              <h4 className="bi-sub">{L('sceneSources')}</h4>
              <ul className="bi-sources">
                {scene.sources.map((s) => (
                  <li key={s.id}>
                    {s.url ? (
                      <a href={s.url} target="_blank" rel="noreferrer noopener">
                        {s.title || s.id}
                      </a>
                    ) : (
                      s.title || s.id
                    )}
                  </li>
                ))}
              </ul>
            </>
          )}
        </>
      )}
    </div>
  );
}

// ---- edit dialog ----------------------------------------------------------------------------------------------------

type Vec3Text = [string, string, string];

interface EditInitial {
  ref: BodyRef;
  name: string;
  kind: string;
  mass: number;
  radius: number;
  position: Vec3;
  velocity: Vec3;
}

const MASS_RULE: FieldRule = { positive: true, max: 1e44 };
const RADIUS_RULE: FieldRule = { positive: true, max: 1e14 };
const POSITION_RULE: FieldRule = { min: -1e20, max: 1e20 };
const VELOCITY_RULE: FieldRule = { min: -0.999 * C, max: 0.999 * C };

function vecTexts(v: Vec3, factor: number): Vec3Text {
  return [inputText(v[0] / factor, 9), inputText(v[1] / factor, 9), inputText(v[2] / factor, 9)];
}

function EditDialog({ initial, onClose }: { initial: EditInitial; onClose: () => void }) {
  const t = useT();
  const L = useL();
  const lang = useLang();
  const system = useSetting('units');
  const pending = useStore(sessionStore, (s) => s.pending);
  const titleId = useId();
  const dialogRef = useRef<HTMLDivElement>(null);
  const nameRef = useRef<HTMLInputElement>(null);

  const startUnits = useMemo(
    () => ({
      mass: autoUnit('mass', initial.mass, system).id,
      radius: autoUnit('radius', initial.radius, system).id,
      position: autoUnit('distance', Math.max(...initial.position.map(Math.abs)), system).id,
      velocity: autoUnit('velocity', Math.max(...initial.velocity.map(Math.abs)), system).id,
    }),
    [initial, system],
  );
  const [units, setUnits] = useState(startUnits);
  const [name, setName] = useState(initial.name);
  const [mass, setMass] = useState(() => inputText(initial.mass / unitById('mass', startUnits.mass).factor, 9));
  const [radius, setRadius] = useState(() => inputText(initial.radius / unitById('radius', startUnits.radius).factor, 9));
  const [position, setPosition] = useState<Vec3Text>(() => vecTexts(initial.position, unitById('distance', startUnits.position).factor));
  const [velocity, setVelocity] = useState<Vec3Text>(() => vecTexts(initial.velocity, unitById('velocity', startUnits.velocity).factor));
  const [touched, setTouched] = useState({ mass: false, radius: false, position: false, velocity: false });
  const [formError, setFormError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const hole = HOLE_KINDS.has(initial.kind);

  // Unit change converts the typed value when it parses (a half-typed value keeps its text).
  const changeUnit = (field: 'mass' | 'radius' | 'position' | 'velocity', next: string) => {
    const q: Quantity = field === 'position' ? 'distance' : field;
    const from = unitById(q, units[field]).factor;
    const to = unitById(q, next).factor;
    const conv = (s: string) => {
      const r = validateField(s, from, {}, t);
      return r.value === null ? s : inputText(r.value / to, 9);
    };
    if (field === 'mass') setMass(conv(mass));
    if (field === 'radius') setRadius(conv(radius));
    if (field === 'position') setPosition(position.map(conv) as Vec3Text);
    if (field === 'velocity') setVelocity(velocity.map(conv) as Vec3Text);
    setUnits({ ...units, [field]: next });
  };

  const massR = validateField(mass, unitById('mass', units.mass).factor, MASS_RULE, t);
  const radiusR = hole ? { value: initial.radius, error: null } : validateField(radius, unitById('radius', units.radius).factor, RADIUS_RULE, t);
  const posR = position.map((s) => validateField(s, unitById('distance', units.position).factor, POSITION_RULE, t));
  const velR = velocity.map((s) => validateField(s, unitById('velocity', units.velocity).factor, VELOCITY_RULE, t));
  const nameError = name.trim() ? null : L('nameRequired');

  // Only fields the user changed go into the patch (an unchanged field keeps the engine's exact value).
  const patch = useMemo((): BodyPatch | null => {
    if (nameError || massR.error || radiusR.error || posR.some((r) => r.error) || velR.some((r) => r.error)) return null;
    const p: BodyPatch = {};
    if (name.trim() !== initial.name) p.name = name.trim();
    if (touched.mass && massR.value !== initial.mass) p.mass = massR.value!;
    if (!hole && touched.radius && radiusR.value !== initial.radius) p.radius = radiusR.value!;
    if (touched.position) {
      const v = posR.map((r) => r.value!) as Vec3;
      if (v.some((x, i) => x !== initial.position[i])) p.position = v;
    }
    if (touched.velocity) {
      const v = velR.map((r) => r.value!) as Vec3;
      if (v.some((x, i) => x !== initial.velocity[i])) p.velocity = v;
    }
    return p;
  }, [nameError, massR, radiusR, posR, velR, name, touched, initial, hole]);

  const invalid = patch === null;
  const empty = !!patch && Object.keys(patch).length === 0;

  // Focus: the name field first; Tab stays inside the dialog; focus returns to the opener on close.
  useEffect(() => {
    const opener = document.activeElement as HTMLElement | null;
    nameRef.current?.focus();
    nameRef.current?.select();
    return () => opener?.focus?.();
  }, []);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    e.stopPropagation(); // nothing typed here reaches the global shortcuts
    if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
      return;
    }
    if (e.key === 'Tab' && dialogRef.current) {
      const items = Array.from(
        dialogRef.current.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), a[href], [tabindex]:not([tabindex="-1"])'),
      );
      if (items.length === 0) return;
      const first = items[0]!;
      const last = items[items.length - 1]!;
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  };

  const apply = async () => {
    setFormError(null);
    if (invalid) {
      setFormError(t('inspector.invalid'));
      return;
    }
    if (empty) {
      setFormError(t('inspector.noChanges'));
      return;
    }
    const s = sessionStore.get();
    const world = s.snapshot;
    if (!sameIdentity(initial.ref, world)) {
      setFormError(L('stale'));
      return;
    }
    if (!bodyOf(initial.ref, world)) {
      setFormError(L('gone'));
      return;
    }
    setBusy(true);
    const ok = await editBody(initial.ref, patch!, L('editLabel', { name: initial.name }));
    setBusy(false);
    if (ok) {
      notify(t('inspector.edited', { label: initial.name }), 'success');
      onClose();
    }
  };

  const disabled = busy || !!pending;
  return createPortal(
    <div
      className="biEdit-backdrop"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget && !busy) onClose();
      }}
    >
      <div ref={dialogRef} className="biEdit-dialog" role="dialog" aria-modal="true" aria-labelledby={titleId} onKeyDown={onKeyDown}>
        <header className="biEdit-head">
          <h2 id={titleId}>{L('editTitle', { name: initial.name })}</h2>
          <button type="button" className="icon-btn biEdit-close" onClick={onClose} aria-label={t('common.close')} title={t('common.close')}>
            <Icon name="close" size={18} />
          </button>
        </header>
        <form
          className="biEdit-form"
          noValidate
          onSubmit={(e) => {
            e.preventDefault();
            void apply();
          }}
        >
          <div className={'qfield' + (nameError ? ' invalid' : '')}>
            <label htmlFor={titleId + '-name'}>{t('inspector.name')}</label>
            <input
              id={titleId + '-name'}
              ref={nameRef}
              className="input"
              value={name}
              maxLength={80}
              disabled={disabled}
              aria-invalid={!!nameError}
              onChange={(e) => setName(e.target.value)}
            />
            {nameError && <span className="qfield-error">{nameError}</span>}
          </div>
          <div className="biEdit-pair">
            <QuantityField
              label={t('inspector.mass')}
              quantity="mass"
              unit={units.mass}
              onUnit={(u) => changeUnit('mass', u)}
              text={mass}
              onText={(s) => {
                setMass(s);
                setTouched((x) => ({ ...x, mass: true }));
              }}
              error={massR.error}
              lang={lang}
              disabled={disabled}
            />
            <QuantityField
              label={t('inspector.radius')}
              quantity="radius"
              unit={units.radius}
              onUnit={(u) => changeUnit('radius', u)}
              text={radius}
              onText={(s) => {
                setRadius(s);
                setTouched((x) => ({ ...x, radius: true }));
              }}
              error={radiusR.error}
              lang={lang}
              disabled={disabled || hole}
              hint={hole ? L('holeRadius') : undefined}
            />
          </div>
          <VectorField
            label={t('inspector.position')}
            quantity="distance"
            unit={units.position}
            onUnit={(u) => changeUnit('position', u)}
            texts={position}
            onTexts={(v) => {
              setPosition(v);
              setTouched((x) => ({ ...x, position: true }));
            }}
            errors={posR.map((r) => r.error) as [string | null, string | null, string | null]}
            lang={lang}
            disabled={disabled}
          />
          <VectorField
            label={t('inspector.velocity')}
            quantity="velocity"
            unit={units.velocity}
            onUnit={(u) => changeUnit('velocity', u)}
            texts={velocity}
            onTexts={(v) => {
              setVelocity(v);
              setTouched((x) => ({ ...x, velocity: true }));
            }}
            errors={velR.map((r) => (r.error ? `${r.error} ${L('speedLimit')}` : null)) as [string | null, string | null, string | null]}
            lang={lang}
            disabled={disabled}
          />
          <p className="biEdit-hint">
            {t('inspector.frame')}. {t('inspector.applyHint')} {L('unchangedHint')}
          </p>
          <p className="biEdit-hint">{t('inspector.liveNote')}</p>
          {formError && (
            <p className="biEdit-error" role="alert">
              {formError}
            </p>
          )}
          <footer className="biEdit-foot">
            <button type="button" className="bi-btn" onClick={onClose} disabled={busy}>
              {t('common.cancel')}
            </button>
            <button type="submit" className="bi-btn bi-btn-primary" disabled={disabled || invalid || empty}>
              {busy ? t('common.loading') : t('common.apply')}
            </button>
          </footer>
        </form>
      </div>
    </div>,
    document.body,
  );
}

// ---- the inspector --------------------------------------------------------------------------------------------------

type Tab = 'props' | 'orbit' | 'source';

export function BodyInspector({ onClose }: { onClose?: () => void }) {
  const t = useT();
  const L = useL();
  const lang = useLang();
  const world = useStore(sessionStore, currentWorld);
  const selection = useStore(sessionStore, (s) => s.selection);
  const pending = useStore(sessionStore, (s) => s.pending);
  const scene = useStore(sessionStore, (s) => s.scene);
  const appearance = useStore(sessionStore, (s) => s.appearance);
  const live = useStore(sessionStore, (s) => s.snapshot);
  const system = useSetting('units');
  const [tab, setTab] = useState<Tab>('props');
  const [editing, setEditing] = useState<EditInitial | null>(null);
  const tabsId = useId();

  const body = bodyOf(selection, world);
  const stale = !!selection && !!world && !sameIdentity(selection, world);
  const canMutate = !!live && !!body && sameIdentity(selection, live) && !pending;

  // The editor belongs to the body it was opened for; another selection closes it (its own apply would refuse anyway).
  useEffect(() => {
    if (editing && (!selection || selection.id !== editing.ref.id || selection.worldId !== editing.ref.worldId)) setEditing(null);
  }, [selection, editing]);

  const nameOf = (b: EngineBody) => bodyDisplayName(b, lang, scene, world, appearance);

  // The editor starts from the displayed name; the patch carries a name only when the player changes it.
  const openEditor = () => {
    if (!body || !selection || !live || !sameIdentity(selection, live)) return;
    setEditing({
      ref: { ...selection },
      name: nameOf(body),
      kind: body.kind,
      mass: body.mass,
      radius: body.radius,
      position: [...body.position] as Vec3,
      velocity: [...body.velocity] as Vec3,
    });
  };

  const remove = async () => {
    if (!body || !selection || !live || !sameIdentity(selection, live)) return;
    const ref: BodyRef = { ...selection };
    const name = nameOf(body);
    const choice = await askConfirm({
      title: L('deleteTitle', { name }),
      body: L('deleteBody'),
      confirm: t('common.delete'),
      cancel: t('common.cancel'),
      danger: true,
    });
    if (choice !== 'confirm') return;
    if (!sameIdentity(ref, sessionStore.get().snapshot)) {
      notify(L('stale'), 'warning');
      return;
    }
    await removeBody(ref, L('removeLabel', { name }));
  };

  const header = (
    <div className="bi-titlebar">
      <h3 className="bi-title">{t('inspector.title')}</h3>
      {onClose && (
        <button type="button" className="icon-btn" onClick={onClose} aria-label={L('close')} title={L('close')}>
          <Icon name="close" size={18} />
        </button>
      )}
    </div>
  );

  if (!body || !world) {
    return (
      <section className="bi-root" aria-label={t('inspector.title')} onKeyDown={stopKeys}>
        {header}
        <div className="bi-empty">
          <Icon name="target" size={28} className="bi-empty-icon" />
          <p>{stale ? L('unselectedStale') : selection && world ? L('gone') : t('inspector.empty')}</p>
          {world && (
            <dl className="bi-grid bi-overview">
              <Row label={t('inspector.overview.bodies')}>{world.bodies.length}</Row>
              <Row label={t('inspector.overview.mass')}>{formatQuantity('mass', world.bodies.reduce((m, b) => m + b.mass, 0), lang, system)}</Row>
            </dl>
          )}
        </div>
      </section>
    );
  }

  const color = bodyColor(body, appearance);
  const kindText = classLabel(body.classTag || body.kind, lang);
  const sub = body.subclass ? classLabel(body.subclass, lang, 'subclass') : '';
  const tabs: { id: Tab; label: string }[] = [
    { id: 'props', label: L('tabProps') },
    { id: 'orbit', label: L('tabOrbit') },
    { id: 'source', label: L('tabSource') },
  ];

  return (
    <section className="bi-root" aria-label={t('inspector.title')} onKeyDown={stopKeys}>
      {header}
      <div className="bi-head">
        <span className="bi-swatch" style={{ background: color, boxShadow: `0 0 14px ${color}` }} aria-hidden="true" />
        <div className="bi-headtext">
          <div className="bi-name" title={nameOf(body)}>
            {nameOf(body)}
          </div>
          <div className="bi-kind">
            {kindText}
            {sub && sub !== kindText ? ` · ${sub}` : ''}
          </div>
        </div>
      </div>
      <div className="bi-actions">
        <button type="button" className="bi-btn" onClick={() => focusBody(body.id)} title={t('inspector.focusBody')}>
          <Icon name="focus" size={16} />
          <span>{t('tool.focus')}</span>
        </button>
        <button type="button" className="bi-btn bi-btn-primary" onClick={openEditor} disabled={!canMutate}>
          <Icon name="sparkle" size={16} />
          <span>{L('edit')}</span>
        </button>
        <button type="button" className="bi-btn bi-btn-danger" onClick={() => void remove()} disabled={!canMutate} title={t('inspector.deleteBody')}>
          <Icon name="trash" size={16} />
          <span>{t('common.delete')}</span>
        </button>
      </div>
      <div className="bi-tabs" role="tablist" aria-label={t('inspector.title')}>
        {tabs.map((x) => (
          <button
            key={x.id}
            type="button"
            role="tab"
            id={`${tabsId}-${x.id}`}
            aria-selected={tab === x.id}
            aria-controls={`${tabsId}-panel`}
            className={'bi-tab-btn' + (tab === x.id ? ' active' : '')}
            onClick={() => setTab(x.id)}
          >
            {x.label}
          </button>
        ))}
      </div>
      <div role="tabpanel" id={`${tabsId}-panel`} aria-labelledby={`${tabsId}-${tab}`} className="bi-panel">
        {tab === 'props' && <PropertiesTab body={body} lang={lang} t={t} />}
        {tab === 'orbit' && <OrbitTab body={body} world={world} lang={lang} t={t} L={L} nameOf={nameOf} />}
        {tab === 'source' && <SourceTab body={body} world={world} scene={scene} lang={lang} L={L} />}
      </div>
      {editing && <EditDialog initial={editing} onClose={() => setEditing(null)} />}
    </section>
  );
}

export default BodyInspector;
