// AiXenix Cosmos Lab web client: sandbox time bar (play/pause, step, rate, date, run state, energy error).

import { useLang, useT } from '../../app/settings';
import { useStore } from '../../app/store';
import { nudgeRate, RATE_PRESETS, sessionStore, setRate, stepOnce, togglePlay } from '../../app/session';
import { formatJulian, formatNumber, formatSpan } from '../../app/units';
import { tr } from '../../content/strings';
import { Icon } from '../Icon';

export function TimeBar() {
  const t = useT();
  const lang = useLang();
  const snap = useStore(sessionStore, (s) => s.snapshot);
  const preview = useStore(sessionStore, (s) => s.preview);
  const rate = useStore(sessionStore, (s) => s.rate);
  const pending = useStore(sessionStore, (s) => s.pending);
  const replacing = pending?.kind === 'load' || pending?.kind === 'restore' || pending?.kind === 'reset';
  const live = !!snap && !replacing;
  const playing = !!snap?.playing;
  const disabledReason = !snap ? t('time.disabled') : replacing ? t('sandbox.pending', { what: pending?.label ?? '' }) : undefined;
  const world = snap ?? preview;
  const jd = world ? world.epochJulianDate + world.simTime / 86400 : 0;
  const run = snap?.run ?? 'no_world';
  const runLabel = playing ? t('time.run.running') : run === 'running' ? t('time.run.user_paused') : t(('time.run.' + run) as Parameters<typeof t>[0]);
  const runTone = run === 'guard_paused' || run === 'speed_paused' ? 'warn' : run === 'faulted' ? 'danger' : playing ? 'ok' : 'idle';
  const err = snap?.conservation.relativeEnergyError ?? 0;
  const last = snap?.lastStep;
  const behind = playing && last && last.limit === 'budget' && last.requestedSeconds > 0;

  return (
    <div className="timebar" role="toolbar" aria-label={t('time.rate')}>
      <button
        type="button"
        className={'play-btn' + (playing ? ' playing' : '')}
        onClick={togglePlay}
        disabled={!live}
        title={disabledReason ?? (playing ? t('time.pause') : t('time.play')) + ' (Space)'}
        aria-label={playing ? t('time.pause') : t('time.play')}
      >
        <Icon name={playing ? 'pause' : 'play'} size={22} />
      </button>
      <button type="button" className="tb-btn" onClick={() => void stepOnce()} disabled={!live || !!pending} title={disabledReason ?? t('time.step', { span: formatSpan(rate, lang) }) + ' (.)'}>
        <Icon name="step" size={18} />
        <span className="tb-btn-label">{t('time.step', { span: formatSpan(rate, lang, 2) })}</span>
      </button>

      <div className="rate" aria-label={t('time.rate')}>
        <button type="button" className="icon-btn sm" onClick={() => nudgeRate(-1)} disabled={!world} aria-label="−" title={t('time.rate') + ' − ([)'}>
          <Icon name="slower" size={16} />
        </button>
        <label className="rate-select">
          <span className="sr-only">{t('time.rate')}</span>
          <select value={RATE_PRESETS.includes(rate) ? String(rate) : 'custom'} disabled={!world} onChange={(e) => e.target.value !== 'custom' && setRate(Number(e.target.value))}>
            {!RATE_PRESETS.includes(rate) && <option value="custom">{t('time.perSecond', { span: formatSpan(rate, lang, 3) })}</option>}
            {RATE_PRESETS.map((r) => (
              <option key={r} value={String(r)}>
                {t('time.perSecond', { span: formatSpan(r, lang, 3) })}
              </option>
            ))}
          </select>
          <Icon name="chevronDown" size={14} />
        </label>
        <button type="button" className="icon-btn sm" onClick={() => nudgeRate(1)} disabled={!world} aria-label="+" title={t('time.rate') + ' + (])'}>
          <Icon name="faster" size={16} />
        </button>
      </div>

      <div className="tb-readouts">
        <div className="tb-readout">
          <span className="tb-k">{t('time.date')}</span>
          <span className="tb-v num">{world ? formatJulian(jd, lang) : '—'}</span>
        </div>
        <div className="tb-readout">
          <span className="tb-k">{t('time.elapsed')}</span>
          <span className="tb-v num">{world ? formatSpan(world.simTime, lang, 4) : '—'}</span>
        </div>
        <div className="tb-readout hide-sm" title={tr('sim.tip', lang)}>
          <span className="tb-k">{t('time.energy')}</span>
          <span className="tb-v num">{snap ? formatNumber(err, lang, 2) : '—'}</span>
        </div>
      </div>

      <span className={`run-chip run-${runTone}`} title={behind ? tr('rate.behind', lang, { achieved: formatSpan(last!.achievedSeconds, lang), requested: formatSpan(last!.requestedSeconds, lang) }) : undefined}>
        <span className="run-dot" aria-hidden="true" />
        {snap ? runLabel : preview ? t('sandbox.world.preview') : t('time.run.no_world')}
        {behind && <Icon name="warning" size={14} />}
      </span>
    </div>
  );
}
