// AiXenix Cosmos Lab web client: saves drawer (browser slots, export, import). Saves stay on this device until exported.

import { useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { useModal } from '../useModal';
import { useLang, useT } from '../../app/settings';
import { useStore } from '../../app/store';
import { exportCurrent, importFile, loadSaveRecord, saveToBrowser, sessionStore } from '../../app/session';
import { askConfirm, notify } from '../../app/notices';
import { deleteSave, downloadJson, listSaves, safeFileName, type SaveRecord } from '../../app/saves';
import { formatRelativeTime, formatSpan } from '../../app/units';
import { tx } from '../../content/catalog';
import { Icon } from '../Icon';

export { defaultSaveName } from '../../app/replaceGuard';
import { defaultSaveName } from '../../app/replaceGuard';

export function SavesPanel({ onClose }: { onClose: () => void }) {
  const t = useT();
  const lang = useLang();
  const snap = useStore(sessionStore, (s) => s.snapshot);
  const pending = useStore(sessionStore, (s) => s.pending);
  const [name, setName] = useState(() => defaultSaveName(lang));
  const [saves, setSaves] = useState<SaveRecord[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const drawerRef = useRef<HTMLElement>(null);
  const nameRef = useRef<HTMLInputElement>(null);
  useModal(drawerRef, onClose, nameRef);

  const refresh = () =>
    listSaves()
      .then((l) => {
        setSaves(l);
        setError(null);
      })
      .catch((e: unknown) => setError(t('saves.storageFailed', { reason: e instanceof Error ? e.message : String(e) })));

  useEffect(() => {
    void refresh();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const busy = !!pending;
  const canSave = !!snap && !busy && name.trim().length > 0;

  const doSave = async (overwrite?: SaveRecord) => {
    const n = overwrite ? overwrite.name : name.trim();
    if (await saveToBrowser(n, overwrite?.id)) await refresh();
  };

  const doLoad = async (rec: SaveRecord) => {
    if (await loadSaveRecord(rec)) onClose();
  };

  const doDelete = async (rec: SaveRecord) => {
    const choice = await askConfirm({ title: t('common.delete'), body: t('saves.confirmDelete', { name: rec.name }), confirm: t('common.delete'), cancel: t('common.cancel'), danger: true });
    if (choice !== 'confirm') return;
    try {
      await deleteSave(rec.id);
      notify(t('saves.deleted', { name: rec.name }), 'success');
    } catch (e) {
      notify(t('saves.storageFailed', { reason: e instanceof Error ? e.message : String(e) }), 'error');
    }
    await refresh();
  };

  const doExportRecord = (rec: SaveRecord) => {
    const file = `${safeFileName(rec.name)}.cosmos.json`;
    downloadJson(file, rec.container);
    notify(t('saves.exported', { file }), 'success');
  };

  // Rendered into <body>: the sandbox is its own stacking context, so a drawer inside it would sit under the header.
  return createPortal(
    <div className="drawer-backdrop" onClick={onClose}>
      <aside ref={drawerRef} tabIndex={-1} className="drawer saves" role="dialog" aria-modal="true" aria-labelledby="saves-title" onClick={(e) => e.stopPropagation()}>
        <div className="panel-head">
          <div>
            <p className="eyebrow">{t('tool.saves')}</p>
            <h2 id="saves-title" className="panel-title">
              {t('saves.title')}
            </h2>
          </div>
          <button type="button" className="icon-btn" onClick={onClose} aria-label={t('common.close')}>
            <Icon name="close" />
          </button>
        </div>
        <div className="panel-body">
          <p className="muted small">{t('saves.lead')}</p>

          <form
            className="save-form"
            onSubmit={(e) => {
              e.preventDefault();
              if (canSave) void doSave();
            }}
          >
            <label className="field-label" htmlFor="save-name">
              {t('saves.name')}
            </label>
            <div className="save-row">
              <input ref={nameRef} id="save-name" className="input" value={name} maxLength={80} onChange={(e) => setName(e.target.value)} disabled={!snap} />
              <button type="submit" className="btn btn-primary" disabled={!canSave}>
                <Icon name="save" size={17} />
                {t('saves.saveNew')}
              </button>
            </div>
            {!snap && <p className="faint small">{t('time.disabled')}</p>}
          </form>

          <div className="save-actions">
            <button type="button" className="btn" disabled={!snap || busy} onClick={() => void exportCurrent(name.trim() || defaultSaveName(lang))}>
              <Icon name="download" size={17} />
              {t('saves.exportCurrent')}
            </button>
            <button type="button" className="btn" disabled={busy} onClick={() => fileRef.current?.click()}>
              <Icon name="upload" size={17} />
              {t('saves.importFile')}
            </button>
            <input
              ref={fileRef}
              type="file"
              accept=".json,application/json"
              hidden
              onChange={async (e) => {
                const f = e.target.files?.[0];
                e.target.value = '';
                if (f && (await importFile(f))) onClose();
              }}
            />
          </div>
          <p className="faint small">{t('saves.importHint')}</p>

          <div className="save-list-wrap">
            {error && <p className="callout danger small">{error}</p>}
            {saves === null && !error && <p className="muted">{t('common.loading')}</p>}
            {saves && saves.length === 0 && <p className="panel-empty muted">{t('saves.empty')}</p>}
            <ul className="save-list">
              {saves?.map((rec) => (
                <li key={rec.id} className={'save-item' + (rec.autosave ? ' autosave' : '')}>
                  <div className="save-info">
                    <span className="save-name">{rec.autosave ? t('saves.autosaveLabel') : rec.name}</span>
                    <span className="save-meta faint">
                      {tx(rec.sceneName ?? undefined, lang) || rec.sceneId} · {t('saves.simTime', { t: formatSpan(rec.simTime, lang) })} · {formatRelativeTime(rec.savedAt, lang)}
                    </span>
                  </div>
                  <div className="save-buttons">
                    <button type="button" className="btn btn-sm btn-primary" disabled={busy} onClick={() => void doLoad(rec)}>
                      {t('common.load')}
                    </button>
                    {!rec.autosave && (
                      <button type="button" className="icon-btn sm" disabled={busy || !snap} onClick={() => void doSave(rec)} title={t('saves.overwrite')} aria-label={t('saves.overwrite')}>
                        <Icon name="save" size={16} />
                      </button>
                    )}
                    <button type="button" className="icon-btn sm" onClick={() => doExportRecord(rec)} title={t('common.export')} aria-label={t('common.export')}>
                      <Icon name="download" size={16} />
                    </button>
                    <button type="button" className="icon-btn sm danger" disabled={busy} onClick={() => void doDelete(rec)} title={t('common.delete')} aria-label={t('common.delete')}>
                      <Icon name="trash" size={16} />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </aside>
    </div>,
    document.body,
  );
}
