// AiXenix Cosmos Lab web client: sandbox popovers: view options and the controls reference.

import { useEffect, useRef, type ReactNode } from 'react';
import { setSetting, useLang, useT, settingsStore } from '../../app/settings';
import { useStore } from '../../app/store';
import { clearTrails } from '../../app/session';
import { formatNumber } from '../../app/units';
import { CONTROLS } from '../../content/handbook';
import { tx } from '../../content/catalog';
import { tr } from '../../content/strings';
import { Toggle } from '../controls';
import { Icon, type IconName } from '../Icon';

function Popover({ onClose, className, children, label }: { onClose: () => void; className?: string; children: ReactNode; label: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const onDown = (e: PointerEvent) => {
      const el = ref.current;
      if (el && !el.contains(e.target as Node) && !(e.target as HTMLElement).closest('[data-popover-anchor]')) onClose();
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('pointerdown', onDown);
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('pointerdown', onDown);
      window.removeEventListener('keydown', onKey);
    };
  }, [onClose]);
  return (
    <div ref={ref} className={'popover ' + (className ?? '')} role="dialog" aria-label={label}>
      {children}
    </div>
  );
}

const SIZE_MIN = 1;
const SIZE_MAX = 1000;

export function ViewMenu({ onClose }: { onClose: () => void }) {
  const t = useT();
  const lang = useLang();
  const s = useStore(settingsStore, (x) => x);
  const slider = Math.log10(Math.min(SIZE_MAX, Math.max(SIZE_MIN, s.sizeScale))) / Math.log10(SIZE_MAX);
  return (
    <Popover onClose={onClose} className="view-menu" label={t('view.title')}>
      <p className="popover-title">{t('view.title')}</p>
      <Toggle checked={s.showLabels} onChange={(v) => setSetting('showLabels', v)} label={`${t('view.labels')} (L)`} />
      <Toggle checked={s.showOrbits} onChange={(v) => setSetting('showOrbits', v)} label={`${t('view.orbits')} (O)`} />
      <Toggle checked={s.showTrails} onChange={(v) => setSetting('showTrails', v)} label={`${t('view.trails')} (T)`} />
      <Toggle checked={s.showGrid} onChange={(v) => setSetting('showGrid', v)} label={`${t('view.grid')} (G)`} />
      <Toggle checked={s.showTracers} onChange={(v) => setSetting('showTracers', v)} label={t('view.tracers')} />
      <div className="size-control">
        <div className="size-head">
          <span>{tr('scale.display', lang)}</span>
          <span className="num">{s.sizeScale <= 1.01 ? tr('scale.true', lang) : `×${formatNumber(s.sizeScale, lang, 3)}`}</span>
        </div>
        <input
          type="range"
          min={0}
          max={1}
          step={0.001}
          value={slider}
          aria-label={tr('scale.display', lang)}
          onChange={(e) => {
            const v = Math.pow(SIZE_MAX, Number(e.target.value));
            setSetting('sizeScale', v < 1.05 ? 1 : Math.round(v));
          }}
        />
        <p className="faint small">{t('view.sizeHint', { f: formatNumber(s.sizeScale, lang, 3) })}</p>
      </div>
      <p className="faint small">{t('view.orbitsHint')}</p>
      <button type="button" className="btn btn-sm" onClick={clearTrails}>
        {t('view.clearTrails')}
      </button>
    </Popover>
  );
}

function MenuItem({ icon, label, detail, disabled, onClick }: { icon: IconName; label: string; detail?: string; disabled: boolean; onClick: () => void }) {
  return (
    <button type="button" role="menuitem" className="menu-item" disabled={disabled} onClick={onClick}>
      <Icon name={icon} size={19} />
      <span className="menu-item-text">
        <span>{label}</span>
        {detail && <span className="menu-item-detail">{detail}</span>}
      </span>
    </button>
  );
}

/** Phone overflow menu: history, reset and camera actions that do not fit in the bar. */
export function ActionsMenu(props: {
  onClose: () => void;
  pending: string | null;
  canUndo: boolean;
  canRedo: boolean;
  undoLabel: string;
  redoLabel: string;
  canReset: boolean;
  canFit: boolean;
  onUndo: () => void;
  onRedo: () => void;
  onReset: () => void;
  onFit: () => void;
  onHelp: () => void;
  onSaves: () => void;
  onMap: () => void;
  mapLabel: string;
}) {
  const t = useT();
  return (
    <Popover onClose={props.onClose} className="actions-menu" label={t('tool.more')}>
      <p className="popover-title">{t('tool.more')}</p>
      {props.pending && (
        <p className="menu-pending" role="status">
          <span className="spinner" />
          {t('sandbox.pending', { what: props.pending })}
        </p>
      )}
      <div role="menu" className="menu-list">
        <MenuItem icon="undo" label={t('tool.undo')} detail={props.canUndo ? props.undoLabel : t('tool.nothingUndo')} disabled={!props.canUndo} onClick={props.onUndo} />
        <MenuItem icon="redo" label={t('tool.redo')} detail={props.canRedo ? props.redoLabel : t('tool.nothingRedo')} disabled={!props.canRedo} onClick={props.onRedo} />
        <MenuItem icon="reset" label={t('tool.reset')} disabled={!props.canReset} onClick={props.onReset} />
        <MenuItem icon="fit" label={t('tool.fit')} disabled={!props.canFit} onClick={props.onFit} />
        <MenuItem icon="galaxy" label={props.mapLabel} disabled={false} onClick={props.onMap} />
        <MenuItem icon="save" label={t('tool.saves')} disabled={false} onClick={props.onSaves} />
        <MenuItem icon="help" label={t('tool.help')} disabled={false} onClick={props.onHelp} />
      </div>
    </Popover>
  );
}

export function HelpMenu({ onClose }: { onClose: () => void }) {
  const t = useT();
  const lang = useLang();
  return (
    <Popover onClose={onClose} className="help-menu" label={t('help.title')}>
      <p className="popover-title">{t('help.title')}</p>
      <table className="controls-table">
        <thead>
          <tr>
            <th />
            <th>{t('help.keys')}</th>
            <th>{t('help.mouse')}</th>
            <th>{t('help.touch')}</th>
          </tr>
        </thead>
        <tbody>
          {CONTROLS.map((c, i) => (
            <tr key={i}>
              <td>{tx(c.action, lang)}</td>
              <td>{c.keyboard ? <kbd>{c.keyboard}</kbd> : ''}</td>
              <td className="faint">{c.mouse ? tx(c.mouse, lang) : ''}</td>
              <td className="faint">{c.touch ? tx(c.touch, lang) : ''}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </Popover>
  );
}
